export interface ProductRecord {
  id: string;
  familySlug: string;
  slug: string;
  title: string;
  tagline: string;
  description: string;
  icon: string | null;
  images: string[];
  links: { website?: string; twitter?: string; github?: string };
  /** Chain the product lives on; null when not chain-specific. */
  chainId: number | null;
  /** 1-5 category ids from the products categories catalog. */
  categories: string[];
  status: "draft" | "published";
  createdBy: string;
  updatedBy: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface ProductInput {
  title?: string;
  tagline?: string;
  description?: string;
  icon?: string | null;
  images?: string[];
  links?: { website?: string; twitter?: string; github?: string };
  chainId?: number | null;
  categories?: string[];
  status?: "draft" | "published";
  slug?: string;
}

export interface ProductListResult {
  ok: boolean;
  products: ProductRecord[];
  canModerate: boolean;
  limit?: number;
  error?: string;
}

export interface ProductResult {
  ok: boolean;
  product?: ProductRecord;
  canModerate?: boolean;
  error?: string;
}

export interface ModuleStoreRecord {
  key: string;
  value: unknown;
  updatedBy?: string | null;
  updatedAt?: string;
}

/** Key-only entry returned by store.list (values omitted). */
export interface ModuleStoreKeyRef {
  key: string;
  updatedBy?: string | null;
  updatedAt?: string;
}

export interface HouseAppContract {
  chainId: number;
  address: string;
  methods: string[];
  /** ABI fragment for the declared methods. Optional for escrow deposits (ERC20 transfer). */
  abi?: unknown;
  /** Per-call native-value cap in atomic units — calls above this are rejected. */
  maxValue?: string;
}

export interface EscrowInput {
  token: string;
  amount: string;
  contract: string;
  action: "deposit" | "withdraw";
}

export interface EscrowResult {
  ok: boolean;
  txHash?: string;
  error?: string;
}

export interface ContractInvokeResult {
  ok: boolean;
  txHash?: string;
  error?: string;
}

/** Result of a host-bridged file upload (stored on the platform IPFS pipeline). */
export interface StorageUploadResult {
  ok: boolean;
  url?: string;
  cid?: string;
  error?: string;
}

export interface ModuleManifest {
  id: string;
  name: string;
  description: string;
  version: string;
  author: string;
  icon?: string;
  tags: string[];
  permissions: ModulePermission[];
  /** Family page tabs where this module can be mounted. */
  surfaces: ModuleSurface[];
  /** UI modules, command modules (forum text commands), or both. Defaults to "ui". */
  integration?: "ui" | "command" | "both";
  /** Forum text commands exposed when integration is "command" or "both". */
  commands?: ModuleCommandSpec[];
  /** Contracts this app may ask the user to interact with. */
  contracts?: HouseAppContract[];
  staking?: {
    amount: string;
    token: string;
  };
  entryUrl?: string; // for external iframe apps
}

export interface ModuleDefinition extends ModuleManifest {
  source: "internal" | "external";
  component?: string; // internal component name
  riskScore: number; // 0-100 computed from permissions
}

/** Install record; mirrors the backend HouseAppInstall model. */
export interface HouseAppInstall {
  id: string;
  appId: string;
  familySlug: string;
  tokenAddress: string | null;
  permissions: ModulePermission[];
  installedBy: string;
  installedAt: string;
  paused: boolean;
}

/** Persistent bottom action button controlled by the hosted app. */
export interface ChromeButtonParams {
  text: string;
  /** Custom background color (css). Falls back to the host accent. */
  color?: string;
  /** Custom label color (css). Falls back to the host accent ink. */
  textColor?: string;
  isVisible?: boolean;
  /** False renders the button dimmed and non-clickable. */
  isActive?: boolean;
  /** True shows a spinner in place of the label. */
  isProgressVisible?: boolean;
}

/** Runtime chrome header the hosted app can drive. */
export interface ChromeHeaderParams {
  title?: string;
  subtitle?: string;
  /** Custom header background (css). Falls back to the host surface. */
  color?: string;
  /** 0..1 loading progress bar; omit to hide. */
  progress?: number;
}

export type ChromeHapticImpact = "light" | "medium" | "heavy" | "rigid" | "soft";
export type ChromeHapticNotification = "error" | "success" | "warning";

/** Host theme snapshot handed to apps so they can restyle to match. */
export interface ChromeTheme {
  colorScheme: "light" | "dark";
  bgColor: string;
  textColor: string;
  hintColor: string;
  buttonColor: string;
  buttonTextColor: string;
}

/** Events the host pushes to the app (FAMILY:EVENT). */
export type ChromeEventType =
  | "mainButtonClicked"
  | "secondaryButtonClicked"
  | "backButtonClicked"
  | "themeChanged"
  | "closed";

export interface ChromeEventMessage {
  event: ChromeEventType;
  data?: unknown;
}

export interface ChromeButtonHandle {
  setParams: (params: ChromeButtonParams) => Promise<void>;
  show: () => Promise<void>;
  hide: () => Promise<void>;
  enable: () => Promise<void>;
  disable: () => Promise<void>;
  showProgress: () => Promise<void>;
  hideProgress: () => Promise<void>;
  onClick: (handler: () => void) => void;
  offClick: (handler: () => void) => void;
}

export interface ChromeBackButton {
  show: () => Promise<void>;
  hide: () => Promise<void>;
  onClick: (handler: () => void) => void;
  offClick: (handler: () => void) => void;
}

/**
 * Host chrome: header, action buttons, back navigation, haptics, theme sync
 * and lifecycle. Rendered by the host runtime around the app surface.
 */
export interface ChromeNamespace {
  /** App finished its first render — the host may hide its loading state. */
  ready: () => Promise<{ ok: boolean }>;
  /** Ask the host to close the app runtime. */
  close: () => Promise<{ ok: boolean }>;
  header: {
    setParams: (params: ChromeHeaderParams) => Promise<void>;
  };
  mainButton: ChromeButtonHandle;
  secondaryButton: ChromeButtonHandle;
  backButton: ChromeBackButton;
  haptic: {
    impact: (style: ChromeHapticImpact) => Promise<void>;
    notification: (type: ChromeHapticNotification) => Promise<void>;
    selection: () => Promise<void>;
  };
  theme: {
    get: () => Promise<ChromeTheme>;
  };
  onEvent: (event: ChromeEventType, handler: (data?: unknown) => void) => void;
  offEvent: (event: ChromeEventType, handler: (data?: unknown) => void) => void;
}

export interface FamilySDK {
  init: (sdkVersion?: string) => Promise<InitResult>;
  getContext: () => Promise<SDKContext>;
  getPermissions: () => Promise<ModulePermission[]>;
  requestPermission: (scope: ModulePermission) => Promise<boolean>;
  identity: {
    getMe: () => Promise<HouseIdentity>;
    getMembers: () => Promise<HouseMember[]>;
  };
  house: {
    getContext: () => Promise<FamilyContext>;
  };
  profile: {
    getProfile: () => Promise<FamilyProfile>;
    getStats: () => Promise<FamilyProfileStats>;
  };
  chart: {
    getPrices: () => Promise<FamilyPrices>;
    getOhlcv: (intervalSeconds?: number) => Promise<FamilyOhlcvResult>;
    getTrades: (opts?: {
      page?: number;
      all?: boolean;
    }) => Promise<FamilyTradesResult>;
  };
  vault: {
    getHoldings: () => Promise<FamilyVaultHoldings>;
    getActivity: () => Promise<FamilyVaultActivity>;
  };
  governance: {
    getProposals: () => Promise<FamilyProposalsResult>;
    getProposal: (id: string) => Promise<FamilyProposalResult>;
  };
  social: {
    post: (input: SocialPostInput) => Promise<SocialPostResult>;
    comment: (postId: string, body: string) => Promise<SocialPostResult>;
    createPoll: (input: PollInput) => Promise<PollResult>;
    votePoll: (postId: string, optionId: string) => Promise<{ ok: boolean; error?: string }>;
  };
  wiki: {
    listPages: () => Promise<WikiListResult>;
    getPage: (slug: string) => Promise<WikiPageResult>;
    savePage: (input: WikiPageInput) => Promise<WikiPageResult>;
    deletePage: (slug: string) => Promise<{ ok: boolean; error?: string }>;
  };
  campaigns: {
    list: () => Promise<CampaignListResult>;
    get: (slug: string) => Promise<CampaignDetailResult>;
    create: (input: CampaignInput) => Promise<CampaignDetailResult>;
    approve: (slug: string, vote: "yes" | "no") => Promise<{ ok: boolean; error?: string }>;
    submit: (slug: string, contentUrl: string, caption?: string, platform?: string) => Promise<{ ok: boolean; submission?: unknown; error?: string }>;
    voteSubmission: (slug: string, submissionId: string, score: number) => Promise<{ ok: boolean; error?: string }>;
    finalizeApproval: (slug: string) => Promise<{ ok: boolean; approved?: boolean; error?: string }>;
    close: (slug: string) => Promise<{ ok: boolean; error?: string }>;
  };
  thesis: {
    list: () => Promise<ThesisListResult>;
    create: (input: ThesisInput) => Promise<ThesisResult>;
    react: (postId: string, stickerId: string) => Promise<{ ok: boolean; removed?: boolean; error?: string }>;
  };
  products: {
    list: (includeDrafts?: boolean) => Promise<ProductListResult>;
    get: (slug: string) => Promise<ProductResult>;
    create: (input: ProductInput) => Promise<ProductResult>;
    update: (slug: string, input: ProductInput) => Promise<ProductResult>;
    publish: (slug: string) => Promise<ProductResult>;
    unpublish: (slug: string) => Promise<ProductResult>;
    remove: (slug: string) => Promise<{ ok: boolean; error?: string }>;
  };
  treasury: {
    getTreasury: () => Promise<HouseTreasury>;
    proposeSpend: (input: SpendProposalInput) => Promise<SpendProposalResult>;
  };
  payments: {
    tip: (input: TipInput) => Promise<TipResult>;
    escrow: (input: EscrowInput) => Promise<EscrowResult>;
    charge: (input: ChargeInput) => Promise<ChargeResult>;
  };
  contract: {
    invoke: (
      address: string,
      method: string,
      args: unknown[],
      options?: { value?: string; abi?: unknown }
    ) => Promise<ContractInvokeResult>;
  };
  /** Module-scoped key-value storage, namespaced by the hosting module's appId. */
  store: {
    get: (key: string) => Promise<ModuleStoreRecord>;
    set: (key: string, value: unknown) => Promise<{ ok: boolean; key: string }>;
    delete: (key: string) => Promise<{ ok: boolean; deleted: number }>;
    list: (prefix?: string) => Promise<ModuleStoreKeyRef[]>;
  };
  /** Host-bridged uploads — the app never talks to IPFS directly. */
  storage: {
    upload: (file: File) => Promise<StorageUploadResult>;
  };
  ui: {
    toast: (message: string, type?: "info" | "success" | "error") => void;
    modal: (options: {
      title: string;
      body: string;
      confirmLabel?: string;
      cancelLabel?: string;
    }) => Promise<boolean>;
  };
  chrome: ChromeNamespace;
  /** Tear down the SDK: remove the message listener and reject all pending calls. */
  dispose: () => void;
}

// postMessage bridge types
export type HouseAppMessageType =
  | "FAMILY:INIT"
  | "FAMILY:INIT:RESPONSE"
  | "FAMILY:CALL"
  | "FAMILY:CALL:RESPONSE"
  | "FAMILY:EVENT";

export interface HouseAppMessage {
  type: HouseAppMessageType;
  id: string;
  namespace: "family-sdk";
  payload?: unknown;
  error?: string;
}

export interface HouseCallPayload {
  method: string;
  args: unknown[];
}
